import { useState } from "react";
import { useNavigate } from "react-router-dom";

const XRAY_IMG =
  "data:image/jpeg;base64,";

const HospitalIcon = ({ size = 20, color = "#22c55e" }) => (
  <svg
    xmlns="http://www.w3.org/2000/svg"
    width={size}
    height={size}
    viewBox="0 0 256 256"
    fill={color}
  >
    <path d="M136,128v72h11.62A12.25,12.25,0,0,0,160,188.53a12,12,0,0,0-5.93-10.87,4.08,4.08,0,0,1-2.06-3.49v-8.79a4,4,0,0,1,5.25-3.81A28.06,28.06,0,0,1,176,187.71c.16,15.56-13,28.29-28.59,28.29H136v16a8,8,0,0,1-16,0V216H96a8,8,0,0,1-8-8.53A8.17,8.17,0,0,1,96.27,200H120V128H104.46c-8.6,0-16,6.6-16.44,15.19a16,16,0,0,0,12.87,16.51,3.94,3.94,0,0,1,3.11,3.89V172a4,4,0,0,1-4,4,36,36,0,0,1-36-36.87C64.47,119.48,81,104,100.68,104H120V24a8,8,0,0,1,16,0v80h32a16,16,0,0,0,16-16.81C183.56,78.6,176.14,72,167.54,72H156a4,4,0,0,1-4-4V44a4,4,0,0,1,4-4h15.22c24.62,0,45.2,20.15,44.77,44.76A44,44,0,0,1,172,128ZM92.66,72H100a4,4,0,0,0,4-4V44a4,4,0,0,0-4-4H64A40,40,0,0,0,24,80v8a8,8,0,0,0,8,8H56A40,40,0,0,0,92.66,72Z"></path>
  </svg>
);

export default function AminexSignIn() {
  const [staffId, setStaffId] = useState("");
  const [password, setPassword] = useState("");
  const [errors, setErrors] = useState({});
  const [loading, setLoading] = useState(false);

  const validate = () => {
    const e = {};
    if (!staffId.trim()) e.staffId = "This field is required";
    if (password.length < 6)
      e.password = "Password must be at least 6 characters";
    return e;
  };
  const navigate = useNavigate();
  const handleSubmit = () => {
    const e = validate();
    setErrors(e);
    if (Object.keys(e).length === 0) {
      setLoading(true);
      setTimeout(() => navigate("/files"), 3000);
    }
  };

  const inputBase = {
    width: "100%",
    height: 44,
    background: "rgba(255,255,255,0.05)",
    border: "1px solid rgba(255,255,255,0.1)",
    borderRadius: 7,
    color: "#fff",
    fontFamily: "inherit",
    fontSize: "0.88rem",
    padding: "0 14px",
    outline: "none",
    boxSizing: "border-box",
  };

  const inputError = {
    borderColor: "rgba(248,113,113,0.5)",
    background: "rgba(248,113,113,0.04)",
  };

  return (
    <div
      style={{
        fontFamily: "'Inter', -apple-system, BlinkMacSystemFont, sans-serif",
        WebkitFontSmoothing: "antialiased",
        minHeight: "100vh",
        display: "flex",
        background: "#0a0e12",
      }}
    >
      {/* Mobile blurred background – only visible below 768px */}
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600&display=swap');
        .aminex-mobile-bg {
          display: block;
          position: fixed;
          inset: 0;
          background-image: url(${XRAY_IMG});
          background-size: cover;
          background-position: center;
          filter: blur(6px) brightness(0.35);
          transform: scale(1.05);
          z-index: 0;
        }
        .aminex-mobile-overlay {
          display: block;
          position: fixed;
          inset: 0;
          background: rgba(10,14,18,0.72);
          z-index: 1;
        }
        .aminex-left {
          display: none;
        }
        @media (min-width: 768px) {
          .aminex-mobile-bg, .aminex-mobile-overlay { display: none; }
          .aminex-left { display: flex; }
          .aminex-card-brand { display: none !important; }
        }
        .aminex-input:focus {
          border-color: rgba(34,197,94,0.5) !important;
          background: rgba(34,197,94,0.05) !important;
        }
        .aminex-input::placeholder { color: rgba(255,255,255,0.2); }
        .aminex-btn:hover { opacity: 0.88; }
        .aminex-btn:active { transform: scale(0.98); }
        .aminex-forgot a:hover { color: rgba(34,197,94,0.75) !important; }
      `}</style>

      <div className="aminex-mobile-bg" />
      <div className="aminex-mobile-overlay" />

      {/* Left panel */}
      <div
        className="aminex-left"
        style={{
          position: "relative",
          width: "50%",
          flexShrink: 0,
          overflow: "hidden",
          flexDirection: "column",
          justifyContent: "flex-end",
        }}
      >
        <div
          style={{
            position: "absolute",
            inset: 0,
            backgroundImage: `url(${XRAY_IMG})`,
            backgroundSize: "cover",
            backgroundPosition: "center",
          }}
        />
        <div
          style={{
            position: "absolute",
            inset: 0,
            background:
              "linear-gradient(135deg, rgba(10,14,18,0.70) 0%, rgba(10,26,15,0.55) 50%, rgba(10,14,18,0.75) 100%)",
          }}
        />
        <div style={{ position: "relative", padding: "2.5rem", zIndex: 1 }}>
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: 10,
              marginBottom: 8,
            }}
          >
            <HospitalIcon size={22} />
            <span
              style={{
                fontSize: "1rem",
                fontWeight: 600,
                color: "#fff",
                letterSpacing: "0.01em",
              }}
            >
              Aminex Hospital
            </span>
          </div>
          <p
            style={{
              fontSize: "0.72rem",
              color: "rgba(255,255,255,0.35)",
              letterSpacing: "0.08em",
              textTransform: "uppercase",
            }}
          >
            Clinical Information System
          </p>
        </div>
      </div>

      {/* Right panel */}
      <div
        style={{
          flex: 1,
          position: "relative",
          zIndex: 2,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          padding: "2rem 1.25rem",
          borderLeft: "1px solid rgba(255,255,255,0.05)",
        }}
      >
        <div style={{ width: "100%", maxWidth: 380 }}>
          {/* Mobile-only brand */}
          <div
            className="aminex-card-brand"
            style={{
              display: "flex",
              alignItems: "center",
              gap: 10,
              marginBottom: "2rem",
            }}
          >
            <HospitalIcon size={20} />
            <span
              style={{ fontSize: "0.95rem", fontWeight: 600, color: "#fff" }}
            >
              Aminex Hospital
            </span>
          </div>

          <h1
            style={{
              fontSize: "1.5rem",
              fontWeight: 600,
              color: "#fff",
              marginBottom: "0.3rem",
              letterSpacing: "-0.02em",
            }}
          >
            Sign In
          </h1>
          <p
            style={{
              fontSize: "0.78rem",
              color: "rgba(255,255,255,0.35)",
              letterSpacing: "0.06em",
              textTransform: "uppercase",
              marginBottom: "2rem",
            }}
          >
            Medical Personnel
          </p>
          <form action="">
            {/* Staff ID */}
            <div style={{ marginBottom: "1rem" }}>
              <label
                style={{
                  display: "block",
                  fontSize: "0.7rem",
                  fontWeight: 500,
                  letterSpacing: "0.1em",
                  textTransform: "uppercase",
                  color: "rgba(255,255,255,0.4)",
                  marginBottom: "0.4rem",
                }}
              >
                Staff ID or Email
              </label>
              <input
                className="aminex-input"
                type="text"
                value={staffId}
                onChange={(e) => {
                  setStaffId(e.target.value);
                  setErrors((p) => ({ ...p, staffId: undefined }));
                }}
                placeholder="e.g. AMX-2024 or name@aminex.health"
                autoComplete="username"
                style={{ ...inputBase, ...(errors.staffId ? inputError : {}) }}
              />
              {errors.staffId && (
                <p
                  style={{
                    fontSize: "0.68rem",
                    color: "#f87171",
                    marginTop: "0.3rem",
                  }}
                >
                  {errors.staffId}
                </p>
              )}
            </div>

            {/* Password */}
            <div style={{ marginBottom: "1rem" }}>
              <label
                style={{
                  display: "block",
                  fontSize: "0.7rem",
                  fontWeight: 500,
                  letterSpacing: "0.1em",
                  textTransform: "uppercase",
                  color: "rgba(255,255,255,0.4)",
                  marginBottom: "0.4rem",
                }}
              >
                Password
              </label>
              <input
                className="aminex-input"
                type="password"
                value={password}
                onChange={(e) => {
                  setPassword(e.target.value);
                  setErrors((p) => ({ ...p, password: undefined }));
                }}
                placeholder="Enter your password"
                autoComplete="current-password"
                style={{ ...inputBase, ...(errors.password ? inputError : {}) }}
              />
              {errors.password && (
                <p
                  style={{
                    fontSize: "0.68rem",
                    color: "#f87171",
                    marginTop: "0.3rem",
                  }}
                >
                  {errors.password}
                </p>
              )}
            </div>

            {/* Forgot */}
            <div
              className="aminex-forgot"
              style={{
                textAlign: "right",
                marginTop: "-0.4rem",
                marginBottom: "1.5rem",
              }}
            >
              <a
                href="#"
                style={{
                  fontSize: "0.72rem",
                  color: "rgba(255,255,255,0.3)",
                  textDecoration: "none",
                }}
              >
                Forgot password?
              </a>
            </div>

            {/* Submit */}
            <button
              className="aminex-btn"
              onClick={handleSubmit}
              disabled={loading}
              style={{
                width: "100%",
                height: 44,
                background: "#22c55e",
                border: "none",
                borderRadius: 7,
                color: "#0a1a0f",
                fontFamily: "inherit",
                fontSize: "0.88rem",
                fontWeight: 600,
                letterSpacing: "0.03em",
                cursor: loading ? "not-allowed" : "pointer",
                opacity: loading ? 0.6 : 1,
                transition: "opacity 0.2s, transform 0.15s",
              }}
            >
              {loading ? "Signing in…" : "Sign In"}
            </button>

            {/* Status bar */}
            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: 6,
                marginTop: "1.75rem",
                paddingTop: "1.25rem",
                borderTop: "1px solid rgba(255,255,255,0.06)",
              }}
            >
              <div
                style={{
                  width: 6,
                  height: 6,
                  borderRadius: "50%",
                  background: "#22c55e",
                  flexShrink: 0,
                }}
              />
              <span
                style={{
                  fontSize: "0.65rem",
                  color: "rgba(255,255,255,0.2)",
                  letterSpacing: "0.05em",
                }}
              >
                Secure connection &nbsp;·&nbsp;{" "}
                <strong
                  style={{ color: "rgba(255,255,255,0.35)", fontWeight: 500 }}
                >
                  Aminex DICOM Viewer v2.1
                </strong>
              </span>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
}
